const AdminEditorStatsCSS = `.editor-stats[hidden],[data-editor-stats][hidden],.seo-audit[hidden],[data-seo-audit][hidden],.page-weight-inspector[hidden],[data-page-weight][hidden],.page-weight-inspector:not(.editor-side-col *),.editor-stats:not(.editor-stats-docked),.seo-audit:not(.editor-side-col *){display:none!important}.editor-stats{display:flex;gap:1rem;flex-wrap:wrap;padding:.65rem 1rem;color:var(--muted);font-size:.78rem}.editor-stats strong{color:var(--ink);font-variant-numeric:tabular-nums}.editor-stats .is-overused,.seo-audit .is-overused{color:var(--red,#dc2626);font-weight:700}.seo-audit{margin-top:.75rem;padding:.75rem 1rem;color:var(--muted);font-size:.82rem}.seo-audit h2{margin:0 0 .45rem;color:var(--ink);font-size:.95rem}.seo-audit ul{display:grid;gap:.25rem;margin:0;padding-inline-start:1.25rem}.editor-stats-docked{margin-top:20px!important;margin-bottom:12px!important;padding:10px 16px!important;background:var(--surface)!important;border:1px solid var(--line)!important;border-radius:var(--radius-lg)!important;box-shadow:var(--shadow-xs);display:flex!important;align-items:center!important;gap:12px!important;flex-wrap:wrap!important;color:var(--muted)!important;font-size:.82rem!important;width:100%!important;box-sizing:border-box!important}.editor-stats-docked>span{display:inline-flex;align-items:center;gap:6px;padding:4px 10px;background:var(--bg-subtle);border:1px solid var(--line);border-radius:var(--radius-md);font-size:.78rem;font-weight:500}.editor-stats-docked strong{color:var(--ink);font-family:var(--font-mono);font-weight:700}.seo-audit-docked{margin-top:.75rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-lg);box-shadow:var(--card-highlight);padding:14px 18px}.page-weight-docked,.editor-side-col .page-weight-inspector{position:static!important;right:auto!important;bottom:auto!important;z-index:auto!important;margin-top:.75rem;width:100%!important;max-width:100%!important;border:1px solid var(--line);background:var(--surface);border-radius:var(--radius-lg);box-shadow:var(--card-highlight);padding:14px 18px;box-sizing:border-box;display:flex!important;flex-direction:column!important;gap:10px}.page-weight-docked .card-title-group,.editor-side-col .page-weight-inspector .card-title-group{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:8px}.page-weight-docked .card-title-group .eyebrow,.editor-side-col .page-weight-inspector .card-title-group .eyebrow{font-size:.68rem;font-weight:700;letter-spacing:.06em;color:var(--muted);margin:0 0 2px}.page-weight-docked .card-title-group h2,.editor-side-col .page-weight-inspector .card-title-group h2{font-size:.92rem;font-weight:700;color:var(--ink);margin:0}.page-weight-docked [data-page-weight-total],.editor-side-col .page-weight-inspector [data-page-weight-total]{font-family:var(--font-mono);font-size:1.1rem;font-weight:700;color:var(--ink)}.page-weight-docked [data-page-weight-state],.editor-side-col .page-weight-inspector [data-page-weight-state]{font-size:.8rem;line-height:1.4;margin:0}.page-weight-docked ul,.editor-side-col .page-weight-inspector ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:6px}.page-weight-docked ul li,.editor-side-col .page-weight-inspector ul li{font-size:.74rem;padding:4px 8px;background:var(--bg-subtle);border:1px solid var(--line);border-radius:var(--radius-xs);color:var(--muted);display:inline-flex;align-items:center;gap:4px}.page-weight-docked ul li strong,.editor-side-col .page-weight-inspector ul li strong{color:var(--ink);font-family:var(--font-mono)}.page-weight-docked [data-page-weight-large-assets],.editor-side-col .page-weight-inspector [data-page-weight-large-assets]{display:grid;gap:4px}.page-weight-inspector[data-weight-state="fast"] [data-page-weight-state]{color:var(--green,#15803d)}.page-weight-inspector[data-weight-state="moderate"] [data-page-weight-state]{color:var(--amber,#b45309)}.page-weight-inspector[data-weight-state="heavy"] [data-page-weight-state]{color:var(--red,#dc2626);font-weight:700}`

const AdminEditorStatsJS = `(()=>{const textOf=e=>e?.value??e?.innerText??e?.textContent??'',set=(root,selector,ok,message)=>{const el=root.querySelector(selector);if(el){el.textContent=(ok?'✓ ':'• ')+message;el.classList.toggle('is-overused',!ok)}return ok};const update=()=>{const bar=document.querySelector('[data-editor-stats]'),audit=document.querySelector('[data-seo-audit]'),weight=document.querySelector('[data-page-weight]');const editor=document.querySelector('.richtext-editor .ql-editor,.richtext-editor[contenteditable="true"],textarea[name="body"]');if(!editor){if(bar)bar.hidden=true;if(audit)audit.hidden=true;if(weight)weight.hidden=true;return}const host=editor.closest('.richtext-field, .richtext-wrap, label')||editor.parentElement;if(bar&&host&&bar.parentElement!==host){host.appendChild(bar);bar.classList.add('editor-stats-docked')}const sideCol=document.querySelector('.editor-side-col');if(audit&&sideCol&&audit.parentElement!==sideCol){sideCol.appendChild(audit);audit.classList.add('seo-audit-docked')}if(weight&&sideCol&&weight.parentElement!==sideCol){sideCol.appendChild(weight);weight.classList.add('page-weight-docked')}if(bar)bar.hidden=!bar.closest('.editor-stats-docked');if(audit)audit.hidden=!audit.closest('.editor-side-col');if(weight)weight.hidden=!weight.closest('.editor-side-col');if(bar&&!bar.hidden){const text=textOf(editor),words=text.trim().match(/\S+/gu)||[];const wEl=bar.querySelector('[data-editor-words]');if(wEl)wEl.textContent=String(words.length);const cEl=bar.querySelector('[data-editor-characters]');if(cEl)cEl.textContent=String(text.length);const rEl=bar.querySelector('[data-editor-reading-time]');if(rEl)rEl.textContent=String(Math.max(1,Math.ceil(words.length/200)));const keyword=document.querySelector('[name="focus_keyword"],[name="keyword"]'),wrap=bar.querySelector('[data-editor-keyword-wrap]');if(keyword?.value.trim()){const needle=keyword.value.trim().toLocaleLowerCase(),matches=words.filter(word=>word.replace(/[^\p{L}\p{N}]/gu,'').toLocaleLowerCase()===needle).length,density=words.length?matches/words.length*100:0;const kdEl=bar.querySelector('[data-editor-keyword-density]');if(kdEl)kdEl.textContent=density.toFixed(1)+'%';wrap.hidden=false;wrap.classList.toggle('is-overused',density>3)}else if(wrap){wrap.hidden=true;wrap.classList.remove('is-overused')}}if(audit&&!audit.hidden){const text=textOf(editor),words=text.trim().match(/\S+/gu)||[];const title=document.querySelector('[name="seo_title"],[name="title"]'),description=document.querySelector('[name="seo_description"],[name="description"],[name="excerpt"]'),titleLength=Array.from(textOf(title).trim()).length,descriptionLength=Array.from(textOf(description).trim()).length,checks=[];checks.push(set(audit,'[data-seo-title]',titleLength>=30&&titleLength<=60,'Başlık '+titleLength+' karakter (öneri 30–60)'));checks.push(set(audit,'[data-seo-description]',descriptionLength>=120&&descriptionLength<=160,'Açıklama '+descriptionLength+' karakter (öneri 120–160)'));const doc=editor.matches('.ql-editor')?editor:new DOMParser().parseFromString(text,'text/html'),headings=[...doc.querySelectorAll('h1,h2,h3,h4,h5,h6')].map(h=>Number(h.tagName.slice(1))),hasH1=headings.includes(1),skipped=headings.some((n,i)=>i>0&&n>headings[i-1]+1);checks.push(set(audit,'[data-seo-heading]',hasH1&&!skipped,hasH1?(skipped?'Başlık seviyelerinde atlama var':'Başlık yapısı uygun'):'H1 başlığı eksik'));const images=[...doc.querySelectorAll('img')],missingAlt=images.filter(img=>!img.getAttribute('alt')?.trim()).length;checks.push(set(audit,'[data-seo-alt]',missingAlt===0,missingAlt?missingAlt+' görselde açıklama eksik':'Görsel açıklamaları mevcut'));const sentences=text.split(/[.!?]+/u).filter(s=>s.trim()).length,average=sentences?words.length/sentences:words.length;checks.push(set(audit,'[data-seo-readability]',average<=25,average?Math.round(average)+' kelime/cümle ortalaması':'İçerik ekleyin'));const scEl=audit.querySelector('[data-seo-score]');if(scEl)scEl.textContent=checks.filter(Boolean).length+'/5'}};document.addEventListener('input',event=>{if(event.target.closest('.richtext-editor,textarea,[name="title"],[name="seo_title"],[name="seo_description"],[name="description"],[name="excerpt"],[name="focus_keyword"],[name="keyword"]'))update()});const init=()=>{update();setTimeout(update,60);setTimeout(update,250);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();document.addEventListener('hydro:admin-navigated',init);})();`
